  });

  test('returns the same color array when source space equals destination space', () => {
    const c = new ColorClass();
    const input = ["RGB", 1, 0, 0];
    const result = c.convert(input, "RGB");
    expect(result).toEqual(input);
  });

  test('handles transparent color array by converting to target color space', () => {
    const c = new ColorClass();
    const result = c.convert(["T"], "G");
    expect(result).toEqual(["G", 0]);
  });
});

