describe('MessageHandler.sendWithStream', () => {
  // Polyfill for Promise.withResolvers if not present
  beforeAll(() => {
    if (!Promise.withResolvers) {
      Promise.withResolvers = function () {
        let resolve, reject;
        const promise = new Promise((res, rej) => {
          resolve = res;
          reject = rej;
        });
        return { promise, resolve, reject };
      };
    }
    // Lightweight ReadableStream polyfill to avoid environment dependencies
    if (!global.ReadableStream) {
      global.ReadableStream = class {
        constructor(underlyingSource, _queueingStrategy) {
          this.desiredSize = 1;
          const controller = { desiredSize: this.desiredSize };
          if (underlyingSource && typeof underlyingSource.start === 'function') {
            underlyingSource.start(controller);
          }
          this._underlyingSource = underlyingSource;
          this._controller = controller;
          this.getReader = () => {
            const self = this;
            return {
              read: () => {
                if (self._underlyingSource && typeof self._underlyingSource.pull === 'function') {
                  const pullController = { desiredSize: self.desiredSize };
                  // Return promise that resolves when the pull promise resolves
                  return self._underlyingSource.pull(pullController).then(() => ({
                    value: undefined,
                    done: false,
                  }));
                }
                return Promise.resolve({ value: undefined, done: true });
              },
              cancel: () => {
                if (self._underlyingSource && typeof self._underlyingSource.cancel === 'function') {
                  self._underlyingSource.cancel();
                }
              },
            };
          };
