    // The start message should have been posted during stream creation
    expect(messages.length).toBeGreaterThanOrEqual(1);
    const first = messages[0].msg;

    expect(first).toMatchObject({
      sourceName: 'srcName',
      targetName: 'dstName',
      action: 'DO_ACTION',
      streamId: 1,
      data: { foo: 'bar' },
