    });

    // Internal state should be initialized
    expect(mh.streamControllers[1]).toBeDefined();
    expect(mh.streamControllers[1].startCall).toBeDefined();
    expect(mh.streamControllers[1].startCall.promise).toBeInstanceOf(Promise);
  });

